// REST surface for send-to-host.
//
// Dashboard side: `transfer/destinations|plan|commit` forward to the one
// agent connection of the source session (AgentRegistry.callOnAgent) with
// the `transfer.*` methods; the extension in that omp process answers and
// enforces control access, and its error codes map to HTTP statuses like the
// other session controls. `commit` first creates the operation here, so the
// worker's credentials are generated by the hub and handed to the extension
// in the RPC; they are never returned to the dashboard or logged.
// `/api/transfers` lists operations (no secrets) and queues cancel and
// recovery commands for the worker.
//
// Worker side (`/api/transfers/:id/worker/...`): the detached worker on the
// source host reports events and fetches commands with the operation's
// Bearer token, and renews it with the renewal secret. Worker routes are
// not rate limited; the global mutation-origin check never blocks them
// because a non-browser client sends no Origin header.

import { type Context, Elysia } from "elysia";
import { AgentCallError, type AgentRegistry } from "./agent-registry";
import { RateLimiter } from "./rate-limit";
import {
  type TransferCredentials,
  TransferRequestError,
  type TransferStore,
  isTerminalState,
} from "./transfer-store";
import {
  SESSION_RPC_ERRORS,
  SESSION_TRANSFER_FEATURE,
  TRANSFER_PROJECT_MODES,
  TRANSFER_RECOVER_ACTIONS,
  TRANSFER_STATES,
  type TransferCommand,
  type TransferEventPayload,
  type TransferPlanParams,
  type TransferProjectMode,
  type TransferRecoverAction,
  type TransferState,
  type TransferView,
} from "./types";

/** Deadlines per call; plan inspects and hashes both project trees. */
const DESTINATIONS_TIMEOUT_MS = 15_000;
const PLAN_TIMEOUT_MS = 120_000;
const COMMIT_TIMEOUT_MS = 60_000;
const SESSION_LOOKUP_TIMEOUT_MS = 15_000;
const INSTANCE_ID_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DESTINATION_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/;
const MAX_ID = 200;
const MAX_PATH = 4096;
const MAX_DETAIL = 1000;
const MAX_ERROR_CODE = 100;
const MAX_ERROR_MESSAGE = 2000;
const MAX_PROGRESS_JSON = 8192;
// biome-ignore lint/suspicious/noControlCharactersInRegex: rejects them
const CONTROL_CHARS = /[\u0000-\u001f\u007f]/;
const HTTP_STATUS_BY_RPC_CODE: Record<number, number> = {
  [SESSION_RPC_ERRORS.notFound]: 404,
  [SESSION_RPC_ERRORS.exists]: 409,
  [SESSION_RPC_ERRORS.forbidden]: 403,
  [SESSION_RPC_ERRORS.invalid]: 400,
  [SESSION_RPC_ERRORS.changed]: 409,
  [SESSION_RPC_ERRORS.busy]: 409,
  [SESSION_RPC_ERRORS.methodNotFound]: 501,
};

interface Failure {
  status: number;
  error: string;
  /** Machine-readable reason a worker can act on. */
  code?: string;
  /** The operation a failed commit left behind. */
  operationId?: string;
}

export interface TransferRoutesOptions {
  /** The hub's public origin; the worker's hub URL falls back to the origin
   *  of the commit request. */
  publicOrigin?: string | null;
  /** Deadline overrides for tests. */
  destinationsTimeoutMs?: number;
  planTimeoutMs?: number;
  commitTimeoutMs?: number;
}

/** HTTP status for a failed agent call: extension error codes per the
 *  session.v1 table, 504 when no reply arrived in time, 502 otherwise. */
function rpcFailure(err: unknown): Failure {
  if (!(err instanceof AgentCallError)) throw err;
  if (err.kind === "timeout") return { status: 504, error: err.message };
  const status =
    err.kind === "remote" && err.code !== undefined
      ? (HTTP_STATUS_BY_RPC_CODE[err.code] ?? 502)
      : 502;
  return { status, error: err.message };
}

function bodyObject(body: unknown): Record<string, unknown> | undefined {
  if (body === undefined || body === null || body === "") return {};
  if (typeof body !== "object" || Array.isArray(body)) return undefined;
  return body as Record<string, unknown>;
}

function isBoundedString(value: unknown, max: number): value is string {
  return typeof value === "string" && value !== "" && value.length <= max;
}

function isProjectMode(value: unknown): value is TransferProjectMode {
  return TRANSFER_PROJECT_MODES.includes(value as TransferProjectMode);
}

/** The token of an `Authorization: Bearer <token>` header. */
function bearerToken(header: string | undefined): string {
  return /^Bearer (\S+)$/.exec(header ?? "")?.[1] ?? "";
}

/** The plan request, or a 400 message. */
function parsePlanBody(body: unknown): TransferPlanParams | string {
  const { destination, projectMode, destinationPath }: Record<string, unknown> =
    bodyObject(body) ?? {};
  if (typeof destination !== "string" || !DESTINATION_RE.test(destination))
    return "destination must be a configured destination name";
  if (projectMode !== undefined && !isProjectMode(projectMode))
    return "projectMode must be create, session-only or update";
  if (
    destinationPath !== undefined &&
    (!isBoundedString(destinationPath, MAX_PATH) ||
      CONTROL_CHARS.test(destinationPath))
  )
    return "destinationPath must be a path string";
  return {
    destination,
    ...(projectMode === undefined ? {} : { projectMode }),
    ...(destinationPath === undefined ? {} : { destinationPath }),
  };
}

interface CommitRequest {
  destination: string;
  planId: string;
  planDigest: string;
  projectMode: TransferProjectMode;
  acceptIncomplete: boolean;
}

/** The commit request, or a 400 message. */
function parseCommitBody(body: unknown): CommitRequest | string {
  const {
    destination,
    planId,
    planDigest,
    projectMode,
    acceptIncomplete,
  }: Record<string, unknown> = bodyObject(body) ?? {};
  if (typeof destination !== "string" || !DESTINATION_RE.test(destination))
    return "destination must be a configured destination name";
  if (!isBoundedString(planId, MAX_ID) || !isBoundedString(planDigest, MAX_ID))
    return "planId and planDigest are required";
  if (!isProjectMode(projectMode))
    return "projectMode must be create, session-only or update";
  if (acceptIncomplete !== undefined && typeof acceptIncomplete !== "boolean")
    return "acceptIncomplete must be a boolean";
  return {
    destination,
    planId,
    planDigest,
    projectMode,
    acceptIncomplete: acceptIncomplete === true,
  };
}

/** The worker event, or a 400 message. */
function parseEventBody(body: unknown): TransferEventPayload | string {
  const { state, detail, error, progress }: Record<string, unknown> =
    bodyObject(body) ?? {};
  if (!TRANSFER_STATES.includes(state as TransferState))
    return `state must be one of ${TRANSFER_STATES.join(", ")}`;
  if (detail !== undefined && !isBoundedString(detail, MAX_DETAIL))
    return `detail must be a string of at most ${MAX_DETAIL} characters`;
  const event: TransferEventPayload = { state: state as TransferState };
  if (detail !== undefined) event.detail = detail as string;
  if (error !== undefined) {
    const fields = bodyObject(error);
    if (
      !fields ||
      !isBoundedString(fields.code, MAX_ERROR_CODE) ||
      !isBoundedString(fields.message, MAX_ERROR_MESSAGE)
    )
      return "error needs a code and a message";
    event.error = { code: fields.code, message: fields.message };
  }
  if (progress !== undefined) {
    const fields = bodyObject(progress);
    if (!fields || JSON.stringify(fields).length > MAX_PROGRESS_JSON)
      return `progress must be an object of at most ${MAX_PROGRESS_JSON} characters`;
    event.progress = fields;
  }
  return event;
}

/** An `after` query value: a non-negative integer, absent meaning 0. */
function parseAfter(value: string | undefined): number | undefined {
  if (value === undefined) return 0;
  return /^\d{1,15}$/.test(value) ? Number(value) : undefined;
}

export function transferRoutes(
  agentRegistry: AgentRegistry,
  store: TransferStore,
  options: TransferRoutesOptions = {},
) {
  const destinationsTimeoutMs =
    options.destinationsTimeoutMs ?? DESTINATIONS_TIMEOUT_MS;
  const planTimeoutMs = options.planTimeoutMs ?? PLAN_TIMEOUT_MS;
  const commitTimeoutMs = options.commitTimeoutMs ?? COMMIT_TIMEOUT_MS;
  // Dashboard mutations only; worker routes are not limited.
  const limiter = new RateLimiter({ max: 20, windowMs: 10_000 });

  function fail(
    set: Context["set"],
    failure: Failure,
    secrets: string[] = [],
  ): { error: string; code?: string; operationId?: string } {
    set.status = failure.status;
    const error = secrets.reduce(
      (message, secret) => message.split(secret).join("[redacted]"),
      failure.error,
    );
    return {
      error,
      ...(failure.code ? { code: failure.code } : {}),
      ...(failure.operationId ? { operationId: failure.operationId } : {}),
    };
  }

  /** The failure for an error thrown inside a route. */
  function storeFailure(set: Context["set"], err: unknown) {
    if (err instanceof TransferRequestError)
      return fail(set, { status: err.status, error: err.message });
    console.error(
      `transfers: request failed: ${err instanceof Error ? err.message : "unknown error"}`,
    );
    return fail(set, {
      status: 500,
      error: "Could not save transfers on the hub.",
    });
  }

  function rateLimited(set: Context["set"]) {
    set.headers["retry-after"] = "1";
    return fail(set, {
      status: 429,
      error: "Rate limit: transfer controls (20 per 10s)",
    });
  }

  /** The agent id to call, or the 400/404/501 that stops the request. */
  function target(
    hostId: string,
    instanceId: string,
  ): { agentId: string } | Failure {
    if (!INSTANCE_ID_RE.test(instanceId))
      return { status: 400, error: "Invalid session instance ID" };
    const agentId = `${hostId}:${instanceId}`;
    const agent = agentRegistry.liveAgent(agentId);
    if (!agent)
      return { status: 404, error: `session '${agentId}' not connected` };
    if (!agent.features.includes(SESSION_TRANSFER_FEATURE))
      return {
        status: 501,
        error: `session's omp-connected extension does not support ${SESSION_TRANSFER_FEATURE}; restart the session to update it`,
      };
    return { agentId };
  }

  /** Forwards `transfer.destinations` or `transfer.plan`. */
  async function forwardRead(
    set: Context["set"],
    routeParams: { id: string; instanceId: string },
    run: (agentId: string) => Promise<unknown>,
  ) {
    const resolved = target(routeParams.id, routeParams.instanceId);
    if (!("agentId" in resolved)) return fail(set, resolved);
    if (!limiter.allow(resolved.agentId)) return rateLimited(set);
    try {
      return await run(resolved.agentId);
    } catch (err) {
      return fail(set, rpcFailure(err));
    }
  }

  /** The session id of an instance, from the host's session list. */
  async function sessionIdOf(
    hostId: string,
    instanceId: string,
  ): Promise<string> {
    const { sessions } = await agentRegistry.callOnHost(
      hostId,
      "collab.list",
      {},
      SESSION_LOOKUP_TIMEOUT_MS,
    );
    const found = sessions.find((s) => s.instanceId === instanceId);
    if (!found)
      throw new TransferRequestError(
        `session '${hostId}:${instanceId}' is not in the host's session list`,
        404,
      );
    return found.sessionId;
  }

  async function commit(
    set: Context["set"],
    routeParams: { id: string; instanceId: string },
    request: Request,
    body: unknown,
  ) {
    const parsed = parseCommitBody(body);
    if (typeof parsed === "string")
      return fail(set, { status: 400, error: parsed });
    const resolved = target(routeParams.id, routeParams.instanceId);
    if (!("agentId" in resolved)) return fail(set, resolved);
    if (!limiter.allow(resolved.agentId)) return rateLimited(set);

    let credentials: TransferCredentials;
    try {
      const sessionId = await sessionIdOf(
        routeParams.id,
        routeParams.instanceId,
      );
      credentials = store.create({
        sessionId,
        host: routeParams.id,
        instance: routeParams.instanceId,
        destination: parsed.destination,
        planDigest: parsed.planDigest,
        projectMode: parsed.projectMode,
      });
    } catch (err) {
      if (err instanceof AgentCallError) return fail(set, rpcFailure(err));
      return storeFailure(set, err);
    }
    const { id, token, renewalSecret } = credentials;
    try {
      await agentRegistry.callOnAgent(
        resolved.agentId,
        "transfer.commit",
        {
          planId: parsed.planId,
          planDigest: parsed.planDigest,
          projectMode: parsed.projectMode,
          acceptIncomplete: parsed.acceptIncomplete,
          operation: {
            id,
            token,
            renewalSecret,
            hubUrl: options.publicOrigin ?? new URL(request.url).origin,
          },
        },
        commitTimeoutMs,
      );
    } catch (err) {
      return commitFailed(set, id, err, [token, renewalSecret]);
    }
    store.announce(id);
    return { operationId: id };
  }

  /**
   * The answer for a commit RPC that failed. A worker that already reported
   * in owns the operation, so the commit counts as made. When the extension
   * replied with an error nothing started and the operation is withdrawn.
   * With no reply (timeout, disconnect) the worker may have been launched,
   * so the operation stays and the answer names it for a later abandon.
   */
  function commitFailed(
    set: Context["set"],
    id: string,
    err: unknown,
    secrets: string[],
  ) {
    if (store.workerStarted(id)) {
      store.announce(id);
      return { operationId: id };
    }
    const failure: Failure =
      err instanceof AgentCallError
        ? rpcFailure(err)
        : {
            status: 502,
            error: err instanceof Error ? err.message : "commit failed",
          };
    if (err instanceof AgentCallError && err.kind === "remote") {
      try {
        store.remove(id);
        return fail(set, failure, secrets);
      } catch (removeErr) {
        console.error(
          `transfers: could not withdraw ${id}: ${removeErr instanceof Error ? removeErr.message : "unknown error"}`,
        );
      }
    }
    store.announce(id);
    return fail(
      set,
      {
        ...failure,
        error: `${failure.error}; the transfer may have started and can be abandoned later`,
        operationId: id,
      },
      secrets,
    );
  }

  /** Looks up `id`, applies the dashboard rate limit, then runs `run`. */
  function mutate(
    set: Context["set"],
    id: string,
    run: (view: TransferView) => unknown,
  ) {
    try {
      const view = store.view(id);
      if (!view)
        return fail(set, { status: 404, error: `transfer '${id}' not found` });
      if (!limiter.allow(`${view.host}:${view.instance}`))
        return rateLimited(set);
      return run(view);
    } catch (err) {
      return storeFailure(set, err);
    }
  }

  /** Queues a command for the worker unless an identical one waits. */
  function queueCommand(
    set: Context["set"],
    id: string,
    type: TransferCommand["type"],
    payload: Record<string, unknown>,
  ) {
    return mutate(set, id, (view) => {
      if (type === "cancel" && isTerminalState(view.state))
        return fail(set, {
          status: 409,
          error: `transfer already ${view.state}`,
        });
      const waiting = view.commands.some(
        (c) =>
          c.ackedAt === undefined &&
          c.type === type &&
          JSON.stringify(c.payload) === JSON.stringify(payload),
      );
      if (!waiting) store.addCommand(id, type, payload);
      return store.view(id);
    });
  }

  /** Runs `handler` for a request carrying the operation's worker token. */
  function asWorker<T>(
    set: Context["set"],
    id: string,
    headers: Record<string, string | undefined>,
    handler: () => T,
  ) {
    try {
      const check = store.checkToken(id, bearerToken(headers.authorization));
      if (check !== "ok") {
        set.headers["www-authenticate"] = 'Bearer realm="transfer"';
        return fail(set, {
          status: 401,
          error: check === "expired" ? "token expired" : "invalid token",
          code: check === "expired" ? "token-expired" : "token-invalid",
        });
      }
      return handler();
    } catch (err) {
      return storeFailure(set, err);
    }
  }

  return new Elysia()
    .post(
      "/api/hosts/:id/sessions/:instanceId/transfer/destinations",
      ({ params, set }) =>
        forwardRead(set, params, (agentId) =>
          agentRegistry.callOnAgent(
            agentId,
            "transfer.destinations",
            {},
            destinationsTimeoutMs,
          ),
        ),
    )
    .post(
      "/api/hosts/:id/sessions/:instanceId/transfer/plan",
      ({ params, body, set }) => {
        const parsed = parsePlanBody(body);
        if (typeof parsed === "string")
          return fail(set, { status: 400, error: parsed });
        return forwardRead(set, params, (agentId) =>
          agentRegistry.callOnAgent(
            agentId,
            "transfer.plan",
            parsed,
            planTimeoutMs,
          ),
        );
      },
    )
    .post(
      "/api/hosts/:id/sessions/:instanceId/transfer/commit",
      ({ params, body, request, set }) => commit(set, params, request, body),
    )

    .get("/api/transfers", () => store.list())
    .get("/api/transfers/:id", ({ params, set }) => {
      const view = store.view(params.id);
      return (
        view ??
        fail(set, { status: 404, error: `transfer '${params.id}' not found` })
      );
    })
    .post("/api/transfers/:id/cancel", ({ params, set }) =>
      queueCommand(set, params.id, "cancel", {}),
    )
    .post("/api/transfers/:id/recover", ({ params, body, set }) => {
      const action = bodyObject(body)?.action;
      if (!TRANSFER_RECOVER_ACTIONS.includes(action as TransferRecoverAction))
        return fail(set, {
          status: 400,
          error: `action must be one of ${TRANSFER_RECOVER_ACTIONS.join(", ")}`,
        });
      return queueCommand(set, params.id, "recover", { action });
    })
    .post("/api/transfers/:id/abandon", ({ params, set }) =>
      mutate(set, params.id, () => {
        store.abandon(params.id);
        return store.view(params.id);
      }),
    )

    .post(
      "/api/transfers/:id/worker/events",
      ({ params, body, headers, set }) =>
        asWorker(set, params.id, headers, () => {
          const event = parseEventBody(body);
          if (typeof event === "string")
            return fail(set, { status: 400, error: event });
          return { ok: true, applied: store.applyEvent(params.id, event) };
        }),
    )
    .get(
      "/api/transfers/:id/worker/commands",
      ({ params, query, headers, set }) =>
        asWorker(set, params.id, headers, () => {
          const after = parseAfter(query.after);
          if (after === undefined)
            return fail(set, {
              status: 400,
              error: "after must be a non-negative integer",
            });
          return {
            commands: store
              .pendingCommands(params.id, after)
              .map(({ seq, type, payload }) => ({ seq, type, payload })),
          };
        }),
    )
    .post(
      "/api/transfers/:id/worker/commands/:seq/ack",
      ({ params, headers, set }) =>
        asWorker(set, params.id, headers, () => {
          if (!/^[1-9]\d{0,14}$/.test(params.seq))
            return fail(set, {
              status: 400,
              error: "seq must be a positive integer",
            });
          store.ackCommand(params.id, Number(params.seq));
          return { ok: true };
        }),
    )
    .post("/api/transfers/:id/worker/renew", ({ params, headers, set }) => {
      set.headers["cache-control"] = "no-store";
      try {
        const secret = bearerToken(headers.authorization);
        if (!store.checkRenewal(params.id, secret)) {
          set.headers["www-authenticate"] = 'Bearer realm="transfer-renewal"';
          return fail(set, {
            status: 401,
            error: "invalid or revoked renewal secret",
            code: "renewal-invalid",
          });
        }
        return store.renew(params.id);
      } catch (err) {
        return storeFailure(set, err);
      }
    })
    .post("/api/transfers/:id/worker/finish", ({ params, headers, set }) =>
      asWorker(set, params.id, headers, () => {
        store.finish(params.id);
        return { ok: true };
      }),
    );
}
